def normalize(text: str, prefix: str) -> str:
    if not isinstance(text, str) or not isinstance(prefix, str):
        raise TypeError("text and prefix must be strings")
    if not prefix.strip():
        raise ValueError("prefix must not be empty")
    return prefix.strip().lower() + ":" + text.strip().lower()

if __name__ == "__main__":
    print(normalize("  Drill STOPPED  ", "urgent"))

def loss(w):
    return (w - 3) ** 2

def grad(w):
    return 2 * (w - 3)

w, rate = 0.0, 0.1
for step in range(5):
    w = w - rate * grad(w)
    print(step + 1, w, loss(w))

h = 0.0001
print("numerical gradient at 1:", (loss(1+h)-loss(1-h))/(2*h))

